    [SerializeField] private Transform _firePoint;
    [SerializeField] private ParticleSystem _firePointParticles;
    [SerializeField] private GameObject _bulletPrefab;
    [SerializeField] private Animator _animator;
    [SerializeField] private TextMeshProUGUI _dashCooldownText;

    [Header("Movement Settings")]
    [SerializeField] private float moveSpeed = 7f;
    [SerializeField] private float accelerationTime = 0.1f;

    [Header("Aiming Settings")]
    [SerializeField] private LayerMask groundMask;
    [SerializeField] private float aimingHeight = 1.6f;
    [SerializeField] private GameObject _worldCursorPrefab;
    [Tooltip("Adjust this value until the character's model faces the exact direction of the shots.")]
    [SerializeField] private float _rotationOffset = 0f;
    [Tooltip("How quickly the character turns to face the aim direction.")]
    [SerializeField] private float _rotationSpeed = 25f;

    [Header("Impulse Sources")]
    [SerializeField] private CinemachineImpulseSource _dashImpulseSource;
    [SerializeField] private CinemachineImpulseSource _gunshotImpulseSource;

    private PlayerMovement _movement;
    private PlayerAiming _aiming;
    private PlayerShooting _shooting;
    private CharacterController _controller;
    private Quaternion _lastRotation;
    private float _turnSpeed;
    private WorldSpaceCursor _worldCursor;

    private readonly int _moveXHash = Animator.StringToHash("MoveX");
    private readonly int _moveYHash = Animator.StringToHash("MoveY");
    private readonly int _speedHash = Animator.StringToHash("Speed");
    private readonly int _turnSpeedHash = Animator.StringToHash("TurnSpeed");

    [Range(25, 100)] public int CurrentHealth = 100;
    [Range(0, 10)] public int CurrentUltimate = 0;

    private static Player _instance;

    void Awake()
    {
        _controller = GetComponent<CharacterController>();
        var mainCamera = Camera.main;

        // Updated constructor to pass groundMask and aimingHeight
        _aiming = new PlayerAiming(mainCamera, transform, groundMask, aimingHeight);

        _movement = new PlayerMovement(_controller, mainCamera.transform, moveSpeed, accelerationTime);
        _shooting = new PlayerShooting(transform, _firePoint, _bulletPrefab, _firePointParticles);

        if (_dashCooldownText != null) _dashCooldownText.gameObject.SetActive(false);
        _lastRotation = transform.rotation;
        _instance = this;

        if (_worldCursorPrefab != null)
        {
            GameObject cursorInstance = Instantiate(_worldCursorPrefab);
            _worldCursor = cursorInstance.GetComponent<WorldSpaceCursor>();
        }
        Cursor.visible = false;
    }

    void Update()
    {
        _aiming.Tick();
        _movement.Tick();

        if (_worldCursor != null)
        {
            // The cursor should be on the ground, so we use GroundPosition
            _worldCursor.UpdatePosition(_aiming.GroundPosition);
        }

        UpdateAnimator();
        UpdateDashCooldownUI();
        if (_movement.JustDashed && _dashImpulseSource != null) 
            _dashImpulseSource.GenerateImpulse();
        if (Input.GetMouseButtonDown(0) && _gunshotImpulseSource != null) 
            _gunshotImpulseSource.GenerateImpulse();
    }

    void LateUpdate()
    {
        // --- ROTATION LOGIC ---
        // Player should look towards the point on the ground, ignoring height.
        Vector3 lookDirection = _aiming.GroundPosition - transform.position;
        lookDirection.y = 0;

        if (lookDirection.sqrMagnitude > 0.01f)
        {
            Quaternion targetLookRotation = Quaternion.LookRotation(lookDirection);
            Quaternion finalRotation = targetLookRotation * Quaternion.Euler(0, _rotationOffset, 0);
            transform.rotation = Quaternion.Slerp(transform.rotation, finalRotation, Time.deltaTime * _rotationSpeed);
        }

        // --- SHOOTING LOGIC ---
        // The shooting direction should point from the fire point to the elevated AimPosition.
        Vector3 P_Start = _firePoint.position;
        Vector3 P_Cel = _aiming.AimPosition;
        Vector3 shootDirection = P_Cel - P_Start;

        // The line `shootDirection.y = 0;` was removed to allow aiming up/down.

        _shooting.Tick(shootDirection.normalized);

        CalculateTurnSpeed();
    }

    public static void TakeDamage(int amount)
    {
        _instance.CurrentHealth -= amount;
        _instance.CurrentHealth = Mathf.Clamp(_instance.CurrentHealth, 0, 100);

        HealthUI.UpdateHealth(_instance.CurrentHealth);
    }

    public static void GetUltimate(int amount)
    {
        _instance.CurrentUltimate += amount;
        _instance.CurrentUltimate = Mathf.Clamp(_instance.CurrentUltimate, 0, 10);

        UltimateUI.UpdateUltimate(_instance.CurrentUltimate);
    }

    private void CalculateTurnSpeed()
    {
        Quaternion currentRotation = transform.rotation;
        Quaternion deltaRotation = currentRotation * Quaternion.Inverse(_lastRotation);

        deltaRotation.ToAngleAxis(out float angle, out Vector3 axis);

        if (float.IsNaN(axis.x)) return;

        float turnDirection = Mathf.Sign(axis.y);
        float turnAnglePerSecond = (angle * turnDirection) / Time.deltaTime;

        _turnSpeed = Mathf.Lerp(_turnSpeed, Mathf.Clamp(turnAnglePerSecond / 360f, -1f, 1f), Time.deltaTime * 20f);
        _lastRotation = currentRotation;
    }

    private void UpdateAnimator()
    {
        if (_animator == null) return;

        Vector3 horizontalVelocity = new(_controller.velocity.x, 0, _controller.velocity.z);
        float currentSpeed = horizontalVelocity.magnitude;
        Vector3 localVelocity = transform.InverseTransformDirection(horizontalVelocity);

        _animator.SetFloat(_speedHash, currentSpeed);
        _animator.SetFloat(_turnSpeedHash, _turnSpeed);
        _animator.SetFloat(_moveXHash, localVelocity.x / moveSpeed);
        _animator.SetFloat(_moveYHash, localVelocity.z / moveSpeed);
    }

    private void UpdateDashCooldownUI()
    {
        if (_dashCooldownText == null) return;

        float cooldown = _movement.DashCooldownTimer;
        if (cooldown > 0)
        {
            _dashCooldownText.gameObject.SetActive(true);
            _dashCooldownText.text = cooldown.ToString("F1");
        }
        else
        {
            _dashCooldownText.gameObject.SetActive(false);
        }
    }
}

using UnityEngine;

public class PlayerAiming
{
    private readonly Camera _cam;
    private readonly Transform _playerTransform;
    private readonly LayerMask _groundMask;
    private readonly float _aimingHeight;

    /// <summary>
    /// The point on the ground, directly below the AimPosition. This is where the cursor indicator should be.
    /// </summary>
    public Vector3 GroundPosition { get; private set; }

    /// <summary>
    /// The actual point in space the weapon aims at, located on a plane at a fixed height.
    /// </summary>
    public Vector3 AimPosition { get; private set; }

    public PlayerAiming(Camera cam, Transform playerTransform, LayerMask groundMask, float aimingHeight)
    {
        _cam = cam;
        _playerTransform = playerTransform;
        _groundMask = groundMask;
        _aimingHeight = aimingHeight;

        // Initialize with fallback values
        AimPosition = _playerTransform.position + Vector3.up * _aimingHeight + _playerTransform.forward * 5f;
        GroundPosition = new Vector3(AimPosition.x, _playerTransform.position.y, AimPosition.z);
    }

    public void Tick()
    {
        // 1. Create an infinite mathematical plane at the desired aiming height, relative to the player's position.
        // This is the plane the player is directly aiming on.
        var aimingPlane = new Plane(Vector3.up, _playerTransform.position + Vector3.up * _aimingHeight);

        // 2. Create a ray from the camera through the mouse cursor.
        var ray = _cam.ScreenPointToRay(Input.mousePosition);

        // 3. Find the intersection point with the aiming plane. This is our main target.
        if (aimingPlane.Raycast(ray, out var enter))
        {
            AimPosition = ray.GetPoint(enter);
        }

        // 4. Find the corresponding ground position by casting a ray downwards from the aim target.
        // This is for the cursor indicator and for player rotation.
        if (Physics.Raycast(AimPosition, Vector3.down, out var hitInfo, Mathf.Infinity, _groundMask))
        {
            GroundPosition = hitInfo.point;
        }
        else
        {
            // Fallback if there is no ground below the cursor (e.g., aiming over a cliff)
            GroundPosition = new Vector3(AimPosition.x, _playerTransform.position.y, AimPosition.z);
        }

        // 5. Debug lines to visualize the logic exactly like in your reference image.
        // Red line from player's weapon to the aim target in the air
        Debug.DrawLine(_playerTransform.position, AimPosition, Color.red); 
        // White line from the aim target down to the ground indicator
        Debug.DrawLine(AimPosition, GroundPosition, Color.white); 
    }
}

using UnityEngine;

public class PlayerAiming
{
    private readonly Camera _cam;
    private readonly Transform _firePoint;
    private readonly LayerMask _groundMask;

    /// <summary>
    /// The point on the ground, directly below the AimPosition. This is where the cursor indicator should be.
    /// </summary>
    public Vector3 GroundPosition { get; private set; }

    /// <summary>
    /// The actual point in space the weapon aims at. It lies on the camera's sight line and the weapon's horizontal plane.
    /// </summary>
    public Vector3 AimPosition { get; private set; }

    public PlayerAiming(Camera cam, Transform firePoint, LayerMask groundMask)
    {
        _cam = cam;
        _firePoint = firePoint;
        _groundMask = groundMask;

        // Initialize with fallback values
        AimPosition = _firePoint.position + _firePoint.forward * 5f;
        GroundPosition = AimPosition - Vector3.up * _firePoint.position.y;
    }

    public void Tick()
    {
        // 1. Create an infinite mathematical plane that is horizontal and passes EXACTLY through the weapon's fire point.
        var shootingPlane = new Plane(Vector3.up, _firePoint.position);

        // 2. Create a ray from the camera through the mouse cursor.
        var ray = _cam.ScreenPointToRay(Input.mousePosition);

        // 3. Find the intersection point of the camera ray and the weapon's shooting plane.
        // This is the ONLY point in 3D space that satisfies both conditions:
        // a) It's on the same level as the weapon.
        // b) It's exactly under the mouse cursor from the camera's perspective.
        if (shootingPlane.Raycast(ray, out var enter))
        {
            AimPosition = ray.GetPoint(enter);
        }

        // 4. Find the corresponding ground position by casting a ray downwards from the aim target.
        if (Physics.Raycast(AimPosition, Vector3.down, out var hitInfo, Mathf.Infinity, _groundMask))
        {
            GroundPosition = hitInfo.point;
        }
        else
        {
            // Fallback if there is no ground below the cursor
            GroundPosition = new Vector3(AimPosition.x, 0, AimPosition.z);
        }

        // 5. Debug lines to visualize the perfect aiming line.
        // The bullet travels along this line. From the camera's view, it will perfectly cover the mouse cursor.
        Debug.DrawLine(_firePoint.position, AimPosition, Color.red);
        // The indicator line from the aim point down to the ground.
        Debug.DrawLine(AimPosition, GroundPosition, Color.white);
    }
}

